head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF30617.xml";
scwin.edu_schdl_id = frame.opener.key_edu_schdl_id;
scwin.gLastJob = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    dts_edu.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=C&CD_ENG_NM=SECU_EDU_TP_CD";
    dts_edu.Reset();
};
scwin.fn_setHeader = function() {
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DISLCS_EDU_SCHDL_INOUT";
    dts_MASTER.Reset();
    dts_MASTER.insertRow();
};
scwin.fn_ReadInfo = function() {
    var url = "/ListedCompany.do?method=readDisclsEduSchdl" + "&EDU_SCHDL_ID=" + scwin.edu_schdl_id + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.reset();
};
scwin.fn_Save = function() {
    if ($c.stf.getObjectValue(cmb_CHRG_TP_CD) == '') {
        $c.win.alert("[담당자구분]을 선택하세요.");
        cmb_CHRG_TP_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_edu) == '') {
        $c.win.alert("[교육구분]을 입력하세요.");
        cmb_edu.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_EDU_CRS_NM) == '') {
        $c.win.alert("[교육과정명]을 입력하세요.");
        txb_EDU_CRS_NM.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_EDU_TM) == '') {
        $c.win.alert("[교육시간]을 입력하세요.");
        txb_EDU_TM.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_EDU_ACK_TM) == '') {
        $c.win.alert("[이수기준(인정시간)]을 입력하세요.");
        txb_EDU_ACK_TM.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_EDU_STRT_DD) == '') {
        $c.win.alert("[교육일정]을 입력하세요.");
        edt_EDU_STRT_DD.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_EDU_INST_NM) == '') {
        $c.win.alert("[교육기관명]을 입력하세요.");
        txb_EDU_INST_NM.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        //setObjectValue(txb_acpt_ddtm,"");
        scwin.gLastJob = "저장";
        trs_Save.Action = "/ListedCompany.do?method=saveDisclsEduSchdl&EDU_SCHDL_ID=" + scwin.edu_schdl_id + "&EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_MASTER)";
        trs_Save.Post();
    }
};
scwin.fn_Delete = function() {
    if (window.confirm("[삭제]하시겠습니까?")) {
        scwin.gLastJob = "삭제";
        $c.stf.setObjectValue(txb_EDU_TM, "");
        var url = "/ListedCompany.do?method=deleteDisclsEduSchdl&EDU_SCHDL_ID=" + scwin.edu_schdl_id + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_MASTER)";
        trs_Save.post();
    }
};
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_EDU_STRT_DD_onclick = function() {
    popUpCalendar2(edt_EDU_STRT_DD);
};
scwin.img_EDU_END_DD_onclick = function() {
    popUpCalendar2(edt_EDU_END_DD);
};
scwin.trs_Save_OnFail = function() {
    scwin.alert_error2(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    //var fr_fn_Search = frame.Provider("../").fn_Search;
    var fr_fn_Search = $c.frame.path("../").fn_Search_Page;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    frame.width = 600;
    frame.height = 300;

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_SetCode();
    if (scwin.edu_schdl_id != "") {
        scwin.fn_ReadInfo();
        cmb_CHRG_TP_CD.setDisabled(true);
    } else {
        scwin.fn_setHeader();
    }
};
